const { ObjectId } = require('mongodb');
const { getDb } = require('../config/mongodb');

function formatSellerResponse(doc) {
  if (!doc) return null;
  return {
    id: doc._id.toString(),
    firebaseUid: doc.firebaseUid,
    businessName: doc.businessName || '',
    ownerName: doc.ownerName || '',
    email: doc.email || '',
    phone: doc.phone || '',
    businessAddress: doc.businessAddress || {},
    status: doc.status || 'pending',
    rejectionReason: doc.rejectionReason || null,
    createdAt: doc.createdAt,
    updatedAt: doc.updatedAt,
    approvedAt: doc.approvedAt || null
  };
}

/**
 * @route   POST /api/seller/profile
 * @desc    Submit or update seller profile application
 * @access  Private (Requires Firebase ID Token)
 */
const registerOrUpdateSellerProfile = async (req, res, next) => {
  try {
    const db = getDb();
    const userId = req.user.uid;

    const { businessName, ownerName, phone, businessAddress } = req.body || {};

    if (!businessName || typeof businessName !== 'string' || businessName.trim().length < 2) {
      return res.status(400).json({
        success: false,
        message: 'Business name is required and must be at least 2 characters.'
      });
    }

    if (!phone || typeof phone !== 'string' || phone.trim().length < 5) {
      return res.status(400).json({
        success: false,
        message: 'Valid phone number is required.'
      });
    }

    const filter = { firebaseUid: userId };
    const update = {
      $setOnInsert: {
        firebaseUid: userId,
        status: 'pending',
        createdAt: new Date()
      },
      $set: {
        businessName: businessName.trim(),
        ownerName: ownerName ? ownerName.trim() : req.user.name || '',
        email: req.user.email || '',
        phone: phone.trim(),
        businessAddress: typeof businessAddress === 'object' ? businessAddress : {},
        updatedAt: new Date()
      }
    };

    const options = { upsert: true, returnDocument: 'after' };
    const seller = await db.collection('sellers').findOneAndUpdate(filter, update, options);

    return res.status(200).json({
      success: true,
      seller: formatSellerResponse(seller)
    });
  } catch (error) {
    next(error);
  }
};

/**
 * @route   GET /api/seller/profile
 * @desc    Get current authenticated seller profile
 * @access  Private (Requires Firebase ID Token)
 */
const getSellerProfile = async (req, res, next) => {
  try {
    const db = getDb();
    const userId = req.user.uid;

    const seller = await db.collection('sellers').findOne({ firebaseUid: userId });
    if (!seller) {
      return res.status(404).json({
        success: false,
        message: 'Seller profile not found. Please register as a seller first.'
      });
    }

    return res.status(200).json({
      success: true,
      seller: formatSellerResponse(seller)
    });
  } catch (error) {
    next(error);
  }
};

/**
 * @route   GET /api/admin/sellers/pending
 * @desc    Get pending seller applications for admin review
 * @access  Private (Admin Role Required)
 */
const getPendingSellers = async (req, res, next) => {
  try {
    const db = getDb();

    const pending = await db
      .collection('sellers')
      .find({ status: 'pending' })
      .sort({ createdAt: -1 })
      .toArray();

    return res.status(200).json({
      success: true,
      count: pending.length,
      sellers: pending.map(formatSellerResponse)
    });
  } catch (error) {
    next(error);
  }
};

/**
 * @route   PATCH /api/admin/sellers/:sellerId/approve
 * @desc    Approve a seller application & elevate role to seller
 * @access  Private (Admin Role Required)
 */
const approveSeller = async (req, res, next) => {
  try {
    const db = getDb();
    const { sellerId } = req.params;

    let query = { firebaseUid: sellerId };
    if (ObjectId.isValid(sellerId)) {
      query = { $or: [{ _id: new ObjectId(sellerId) }, { firebaseUid: sellerId }] };
    }

    const seller = await db.collection('sellers').findOneAndUpdate(
      query,
      {
        $set: {
          status: 'approved',
          approvedAt: new Date(),
          rejectionReason: null,
          updatedAt: new Date()
        }
      },
      { returnDocument: 'after' }
    );

    if (!seller) {
      return res.status(404).json({
        success: false,
        message: 'Seller application not found.'
      });
    }

    // Elevate user role to seller in users collection
    await db.collection('users').updateOne(
      { firebaseUid: seller.firebaseUid },
      { $set: { role: 'seller', updatedAt: new Date() } }
    );

    return res.status(200).json({
      success: true,
      seller: formatSellerResponse(seller)
    });
  } catch (error) {
    next(error);
  }
};

/**
 * @route   PATCH /api/admin/sellers/:sellerId/reject
 * @desc    Reject a seller application
 * @access  Private (Admin Role Required)
 */
const rejectSeller = async (req, res, next) => {
  try {
    const db = getDb();
    const { sellerId } = req.params;
    const { reason } = req.body || {};

    let query = { firebaseUid: sellerId };
    if (ObjectId.isValid(sellerId)) {
      query = { $or: [{ _id: new ObjectId(sellerId) }, { firebaseUid: sellerId }] };
    }

    const seller = await db.collection('sellers').findOneAndUpdate(
      query,
      {
        $set: {
          status: 'rejected',
          rejectedAt: new Date(),
          rejectionReason: reason ? String(reason).trim() : 'Application requirements not met',
          updatedAt: new Date()
        }
      },
      { returnDocument: 'after' }
    );

    if (!seller) {
      return res.status(404).json({
        success: false,
        message: 'Seller application not found.'
      });
    }

    return res.status(200).json({
      success: true,
      seller: formatSellerResponse(seller)
    });
  } catch (error) {
    next(error);
  }
};

module.exports = {
  registerOrUpdateSellerProfile,
  getSellerProfile,
  getPendingSellers,
  approveSeller,
  rejectSeller
};
